function [volume, tuna_assumed] = catalogue_volume(a, b, c, boxed, tuna)
%CATALOGUE_VOLUME  The unit's volume [L]: a box of sides a, b, c [mm] when the datasheet gives one (boxed), else a 0.2U tuna can per unit
%   when it says so (tuna, an assumption), else not stated (nan).
%   a: real[1] (passed a plain number)
%   b: real[1] (passed a plain number)
%   c: real[1] (passed a plain number)
%   boxed: bool (passed true or false)
%   tuna: bool (passed true or false)
%   returns volume: real[1] (passed a plain number)
%   returns tuna_assumed: bool (passed true or false)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    volume = 0;
    tuna_assumed = false;
    [a0, a1, a2, a3, a4, a5, a6, a7, a8, a9, a10, a11, a12, tv] = asils.models.catderive.catalogue_rules();
    volume = NaN;
    tuna_assumed = false;
    if boxed
        volume = (((a * b) * c) * 0.000001);
    elseif tuna
        volume = tv;
        tuna_assumed = true;
    end
end
